insert into public.styles (id,category_id,name,slug,short_description,full_description,image_url,tags,featured,active,display_order,estimated_duration) values
('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','Bob elegante','bob-elegante','Una silueta definida, moderna y fácil de adaptar a tu estilo.','Un corte de líneas limpias que enmarca el rostro y se adapta después de evaluar facciones y movimiento natural.','/images/styles/corte-bob.svg',array['moderno','media melena','elegante'],true,true,1,'60 a 90 minutos'),
('20000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000001','Largo en capas','largo-en-capas','Capas suaves que aportan movimiento sin perder el largo.','La distribución de las capas se personaliza según densidad, textura y rutina.','/images/styles/corte-capas.svg',array['capas','cabello largo','movimiento'],false,true,2,'60 a 90 minutos'),
('20000000-0000-4000-8000-000000000003','10000000-0000-4000-8000-000000000001','Corte mariposa','corte-mariposa','Volumen ligero y capas envolventes alrededor del rostro.','Capas amplias que crean volumen y una caída envolvente.','/images/styles/corte-mariposa.svg',array['volumen','capas','rostro'],false,true,3,null),
('20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000001','Flequillo cortina','flequillo-cortina','Un marco suave para renovar el look con sutileza.','Flequillo abierto que se integra al resto del cabello.','/images/styles/corte-bob.svg',array['flequillo','suave','contorno'],false,true,4,null),
('20000000-0000-4000-8000-000000000005','10000000-0000-4000-8000-000000000002','Balayage miel','balayage-miel','Reflejos cálidos y luminosos con una transición delicada.','La propuesta se define después de revisar base, historial y estado del cabello.','/images/styles/color-miel.svg',array['balayage','cálido','luminoso'],true,true,5,'Según evaluación del cabello'),
('20000000-0000-4000-8000-000000000006','10000000-0000-4000-8000-000000000002','Rubio beige','rubio-beige','Un rubio equilibrado, suave y sofisticado.','La técnica y el nivel de aclaración se determinan según la base natural.','/images/styles/color-beige.svg',array['rubio','beige','neutral'],false,true,6,null),
('20000000-0000-4000-8000-000000000007','10000000-0000-4000-8000-000000000002','Morena iluminada','morena-iluminada','Puntos de luz estratégicos que respetan la profundidad natural.','Una iluminación sutil que conserva la identidad de una base oscura.','/images/styles/color-morena.svg',array['morena','reflejos','dimensión'],false,true,7,null),
('20000000-0000-4000-8000-000000000008','10000000-0000-4000-8000-000000000002','Cobrizo suave','cobrizo-suave','Calidez delicada con reflejos cobrizos elegantes.','La intensidad final se acuerda durante la evaluación previa.','/images/styles/color-miel.svg',array['cobrizo','cálido','reflejos'],false,true,8,null),
('20000000-0000-4000-8000-000000000009','10000000-0000-4000-8000-000000000003','Ondas glam','ondas-glam','Ondas pulidas con movimiento y un acabado luminoso.','El volumen y la terminación se adaptan al largo del cabello.','/images/styles/peinado-ondas.svg',array['ondas','evento','glam'],true,true,9,'60 a 90 minutos'),
('20000000-0000-4000-8000-000000000010','10000000-0000-4000-8000-000000000003','Recogido elegante','recogido-elegante','Una composición refinada con sujeción cómoda.','La altura, el volumen y los detalles se definen según el look completo.','/images/styles/peinado-recogido.svg',array['recogido','elegante','evento'],false,true,10,null),
('20000000-0000-4000-8000-000000000011','10000000-0000-4000-8000-000000000003','Trenza romántica','trenza-romantica','Textura suave y detalles delicados.','Puede integrarse en recogidos o semirrecogidos según el evento.','/images/styles/peinado-ondas.svg',array['trenza','romántico','textura'],false,true,11,null),
('20000000-0000-4000-8000-000000000012','10000000-0000-4000-8000-000000000005','Hidratación profunda','hidratacion-profunda','Cuidado intensivo para recuperar suavidad y flexibilidad.','El protocolo se selecciona después de observar las necesidades del cabello.','/images/styles/tratamiento-hidratacion.svg',array['hidratación','suavidad','cuidado'],false,true,12,null),
('20000000-0000-4000-8000-000000000013','10000000-0000-4000-8000-000000000005','Reparación capilar','reparacion-capilar','Rutina adaptada a cabellos sensibilizados.','La propuesta final depende del diagnóstico profesional.','/images/styles/tratamiento-nutricion.svg',array['reparación','nutrición','cabello sensibilizado'],false,true,13,null),
('20000000-0000-4000-8000-000000000014','10000000-0000-4000-8000-000000000004','Peinado clásico de quinceañera','peinado-clasico-quinceanera','Un peinado especial y elegante para acompañar todo el evento.','El diseño se adapta al vestido, accesorios y personalidad.','/images/styles/quince-clasico.svg',array['quinceañera','clásico','evento'],true,true,14,null),
('20000000-0000-4000-8000-000000000015','10000000-0000-4000-8000-000000000004','Semirrecogido con ondas','semirrecogido-con-ondas','Movimiento, delicadeza y comodidad en un look juvenil.','Se personaliza para integrar accesorios y acompañar el evento.','/images/styles/quince-semirrecogido.svg',array['quinceañera','semirrecogido','ondas'],false,true,15,null)
insert into public.professionals (id,name,slug,role,short_description,full_description,image_url,whatsapp_number,specialties,featured,active,display_order,availability_note) values
('30000000-0000-4000-8000-000000000001','Marilyn','marilyn','Directora estilista','Una mirada integral para crear color y estilo en armonía.','Su propuesta comienza con una conversación y evaluación cuidadosa.','/images/professionals/marilyn.svg',null,array['Coloración','Balayage','Mechas','Asesoría de imagen'],true,true,1,'Disponibilidad sujeta a consulta y confirmación.'),
('30000000-0000-4000-8000-000000000002','Laura','laura','Estilista','Cortes con movimiento y terminaciones pulidas.','Cada corte se adapta a textura, facciones y rutina.','/images/professionals/laura.svg',null,array['Cortes','Brushing','Balayage'],true,true,2,'Disponibilidad sujeta a consulta y confirmación.'),
('30000000-0000-4000-8000-000000000003','Camila','camila','Especialista en eventos','Peinados elegantes y cómodos para momentos especiales.','Diseña peinados considerando el look completo y la duración del evento.','/images/professionals/camila.svg',null,array['Peinados','Recogidos','Quinceañeras'],true,true,3,'Disponibilidad sujeta a consulta y confirmación.'),
('30000000-0000-4000-8000-000000000004','Sofía','sofia','Colorista','Matices luminosos con especial atención al cuidado.','Trabaja propuestas de iluminación adaptadas a la base y al historial.','/images/professionals/sofia.svg',null,array['Coloración','Mechas','Balayage'],false,true,4,'Disponibilidad sujeta a consulta y confirmación.'),
('30000000-0000-4000-8000-000000000005','Valentina','valentina','Especialista en cuidado capilar','Cuidado personalizado para recuperar suavidad y brillo.','Evalúa las necesidades del cabello para orientar hidratación o reparación.','/images/professionals/valentina.svg',null,array['Tratamientos','Hidratación','Asesoría de imagen'],false,true,5,'Disponibilidad sujeta a consulta y confirmación.'),
('30000000-0000-4000-8000-000000000006','Ana','ana','Estilista integral','Versatilidad y atención cercana para cortes y peinados.','Acompaña cambios sutiles y preparaciones para eventos.','/images/professionals/ana.svg',null,array['Cortes','Peinados','Brushing'],false,true,6,'Disponibilidad sujeta a consulta y confirmación.')
