-- Datos provisionales e idempotentes. Reemplazar textos e imágenes por información real desde el panel.
on conflict (slug) do update set name=excluded.name, description=excluded.description, display_order=excluded.display_order;

on conflict (slug) do update set category_id=excluded.category_id,name=excluded.name,short_description=excluded.short_description,full_description=excluded.full_description,image_url=excluded.image_url,tags=excluded.tags,featured=excluded.featured,active=excluded.active,display_order=excluded.display_order,estimated_duration=excluded.estimated_duration;

on conflict (slug) do update set name=excluded.name,role=excluded.role,short_description=excluded.short_description,full_description=excluded.full_description,image_url=excluded.image_url,specialties=excluded.specialties,featured=excluded.featured,active=excluded.active,display_order=excluded.display_order,availability_note=excluded.availability_note;

on conflict do nothing;

on conflict (key) do nothing;
